{"content":"/**
 * RFC 4180 style CSV reader and writer with a configurable delimiter and quote
 * character, byte-order-mark handling and exact positions on failure.
 */

/** Failure raised by the CSV reader and writer. */
export class CsvError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [line] 1-based line the failure was found on
   * @param {number} [column] 1-based column, counted in UTF-16 code units
   */
  constructor(message, line, column) {
    super(message);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

/**
 * Read a CSV document into records.
 *
 * @param {string} text document source
 * @param {{ delimiter?: string, quote?: string, strictWidth?: boolean }} [options] dialect and width policy
 * @returns {string[][]} one array of field values per record
 */
export function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new CsvError('input must be a string');
  }

  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  const strictWidth = options.strictWidth ?? false;

  if (delimiter.length !== 1) {
    throw new CsvError('delimiter must be a single character');
  }
  if (quote.length !== 1) {
    throw new CsvError('quote must be a single character');
  }
  if (delimiter === quote) {
    throw new CsvError('delimiter and quote must differ');
  }
  if (delimiter === '\n' || delimiter === '\r' || delimiter === '\r\n') {
    throw new CsvError('delimiter and quote must not be line terminators');
  }
  if (quote === '\n' || quote === '\r' || quote === '\r\n') {
    throw new CsvError('delimiter and quote must not be line terminators');
  }

  // Handle BOM at the start
  if (text.startsWith('\uFEFF')) {
    text = text.slice(1);
  }

  const records = [];
  let currentRecord = [];
  let currentField = '';
  let i = 0;
  let line = 1;
  let column = 1;
  let inQuotes = false;
  let quotedFieldStartLine = 0;
  let quotedFieldStartColumn = 0;

  while (i < text.length) {
    const ch = text[i];

    if (!inQuotes) {
      // Check for line terminators
      if (ch === '\r' && i + 1 < text.length && text[i + 1] === '\n') {
        // CRLF
        currentRecord.push(currentField);
        records.push(currentRecord);
        currentRecord = [];
        currentField = '';
        i += 2;
        line++;
        column = 1;
        continue;
      } else if (ch === '\n' || ch === '\r') {
        // LF or CR
        currentRecord.push(currentField);
        records.push(currentRecord);
        currentRecord = [];
        currentField = '';
        i++;
        line++;
        column = 1;
        continue;
      }

      // Check for delimiter
      if (ch === delimiter) {
        currentRecord.push(currentField);
        currentField = '';
        i++;
        column++;
        continue;
      }

      // Check for quote
      if (ch === quote) {
        inQuotes = true;
        quotedFieldStartLine = line;
        quotedFieldStartColumn = column;
        i++;
        column++;
        continue;
      }

      // Regular character
      currentField += ch;
      i++;
      column++;
    } else {
      // Inside quotes
      if (ch === quote) {
        // Check for doubled quote
        if (i + 1 < text.length && text[i + 1] === quote) {
          currentField += quote;
          i += 2;
          column += 2;
        } else {
          // Closing quote
          inQuotes = false;
          i++;
          column++;

          // After closing quote, only delimiter, line terminator, or end is allowed
          if (i < text.length) {
            const nextCh = text[i];
            if (nextCh !== delimiter && 
                nextCh !== '\n' && 
                nextCh !== '\r' &&
                !(nextCh === '\r' && i + 1 < text.length && text[i + 1] === '\n')) {
              throw new CsvError(`unexpected character after closing quote: ${nextCh}`, line, column);
            }
          }
          continue;
        }
      } else {
        // Regular character inside quotes
        currentField += ch;
        i++;
        column++;

        // Handle line terminators inside quotes
        if (ch === '\r' && i < text.length && text[i] === '\n') {
          // CRLF inside quotes - don't advance i here, let next iteration handle it
          line++;
          column = 1;
        } else if (ch === '\n' || ch === '\r') {
          // LF or CR inside quotes
          line++;
          column = 1;
        }
      }
    }
  }

  // Handle last field and record
  if (inQuotes) {
    throw new CsvError('unterminated quoted field', quotedFieldStartLine, quotedFieldStartColumn);
  }

  currentRecord.push(currentField);
  if (currentRecord.length > 0 || currentField !== '' || records.length > 0) {
    records.push(currentRecord);
  }

  // Handle strictWidth
  if (strictWidth && records.length > 1) {
    const expectedWidth = records[0].length;
    for (let i = 1; i < records.length; i++) {
      if (records[i].length !== expectedWidth) {
        throw new CsvError(`expected ${expectedWidth} fields, got ${records[i].length}`, i + 1);
      }
    }
  }

  return records;
