  if (text.startsWith('\uFEFF')) {
    text = text.slice(1);
  }

  const records = [];
  let currentRecord = [];
  let currentField = '';
  let i = 0;
  let line = 1;
  let column = 1;
  let inQuotes = false;
  let quotedFieldStartLine = 0;
  let quotedFieldStartColumn = 0;

  while (i < text.length) {
