        currentField = '';
        i++;
        column++;
        continue;
      }

      // Check for quote
      if (ch === quote) {
        inQuotes = true;
        quotedFieldStartLine = line;
        quotedFieldStartColumn = column;
        i++;
        column++;
        continue;
